// Deterministic actions behind the assistant. Each one is a plain function: (message, ctx) -> reply text.
// The router (router.mjs) only chooses which action runs; nothing here is generated by a model. Numbers and names are
// pulled out of the message with regular expressions, validated, and either used or asked for again.

import { COUNTRIES, TEMPLATES } from './constants.js';
import { INTENTS, classify, threshold } from './router.mjs';
import { profileFacts, yearsOfExperience, list, cap } from './profile.mjs';
import { scoreResume } from './ats.mjs';
import * as offline from './offline.mjs';

const pick = (a) => a[Math.floor(Math.random() * a.length)];

/* ---------- parameter extraction (regular expressions only) ---------- */
// Text after the first colon or line break, or inside quotation marks: "improve this bullet: led a team of 5".
export function extractPayload(message) {
  const m = String(message || '');
  const quoted = /["“”]([^"“”]{8,})["“”]/.exec(m);
  if (quoted) return quoted[1].trim();
  const i = m.search(/[:\n]/);
  return i >= 0 ? m.slice(i + 1).trim() : '';
}

const COUNTRY_WORDS = {
  AF: ['uganda', 'kenya', 'tanzania', 'rwanda', 'burundi', 'ethiopia', 'nigeria', 'ghana', 'zambia', 'zimbabwe', 'malawi', 'south africa', 'africa', 'east africa', 'west africa', 'south sudan', 'sudan', 'somalia', 'cameroon', 'senegal'],
  US: ['usa', 'united states', 'america', 'american', 'us'],
  CA: ['canada', 'canadian'],
  UK: ['uk', 'united kingdom', 'britain', 'british', 'england', 'scotland', 'wales'],
  EU: ['europe', 'european', 'eu', 'germany', 'france', 'spain', 'italy', 'netherlands', 'ireland', 'sweden', 'poland', 'belgium', 'portugal'],
  AU: ['australia', 'australian', 'new zealand', 'nz'],
  IN: ['india', 'indian'],
  ME: ['dubai', 'uae', 'emirates', 'saudi', 'qatar', 'kuwait', 'oman', 'bahrain', 'gulf', 'middle east'],
};
export function extractCountry(message) {
  const m = ` ${String(message || '').toLowerCase().replace(/[^a-z\s]/g, ' ')} `;
  let best = null;
  for (const [id, words] of Object.entries(COUNTRY_WORDS)) for (const w of words) {
    if (m.includes(` ${w} `) && (!best || w.length > best.len)) best = { id, len: w.length, word: w };
  }
  return best ? { id: best.id, word: best.word } : null;
}

const NOT_A_TITLE = new Set(['me', 'my cv', 'my resume', 'my job', 'the job', 'a job', 'this job', 'this role', 'the role', 'a role', 'work', 'my application', 'it']);
export function extractJob(message) {
  const m = String(message || '').split(/[:\n]/)[0].trim();
  const lower = m.replace(/\s+/g, ' ');
  let title = /\b(?:for|as|to be)\s+(?:an?\s+|the\s+)?([A-Za-z][A-Za-z &/-]{2,50}?)\s+(?:job|role|position|post|vacancy|interview)\b/i.exec(lower)?.[1];
  if (!title) title = /\b(?:for|as)\s+(?:an?\s+|the\s+)?([A-Za-z][A-Za-z &/-]{2,40}?)\s*(?:at\b.*)?$/i.exec(lower)?.[1];
  title = title ? title.trim().replace(/\s+(please|pls|now)$/i, '') : '';
  if (NOT_A_TITLE.has(title.toLowerCase())) title = '';
  const company = /\bat\s+([A-Z][\w&.-]*(?:\s+[A-Z][\w&.-]*){0,3})/.exec(m)?.[1] || '';
  return { title, company };
}

const needProfile = (f) => !(f.name || f.hasExperience || f.hasEducation || f.skills.length);
const EMPTY = 'Your profile is empty, so there is nothing for me to work from yet. Open Profile, add your details, experience, education and skills, then ask me again.';

/* ---------- actions ---------- */
const GREETINGS = [
  'Hello! Good to see you. What would you like to work on today?',
  'Hi there! I can help with your CV, cover letters and interview prep. Where shall we start?',
  'Hey! Ready when you are. Ask me anything about your CV or job search.',
  'Hello and welcome back! Tell me what you want to sort out today.',
  'Oli otya! I am here to help with your CV and applications. What do you need?',
  'Hi! Your CV is in good hands. What shall we improve?',
];
export function greet_user(_message, ctx) {
  const first = String(ctx.content?.personal?.fullName || '').trim().split(/\s+/)[0];
  const line = pick(GREETINGS);
  return { reply: first && Math.random() < 0.5 ? line.replace(/^(\w+)!?/, (m0) => `${m0.replace(/!$/, '')}, ${first}!`) : line };
}

export function help_menu() {
  const lines = Object.entries(ACTIONS).filter(([k]) => k !== 'greet_user' && k !== 'help_menu').map(([, a]) => `- ${a.title}: ${a.example}`);
  return { reply: `Here is what I can do. Just type it the way you would say it:\n\n${lines.join('\n')}\n\nI work offline from your profile, so the more complete it is, the better my answers.` };
}

export function write_summary(message, ctx) {
  const f = profileFacts(ctx.content);
  if (needProfile(f)) return { reply: EMPTY };
  const job = extractJob(message);
  const options = offline.summaryOptions(ctx.content, job.title ? { title: job.title, company: job.company, description: '' } : null);
  return { reply: `Here are ${options.length} summaries to choose from${job.title ? ` for a ${job.title} role` : ''}:\n\n${options.slice(0, 3).map((o, i) => `${i + 1}. (${o.label}) ${o.text}`).join('\n\n')}\n\nUse "Write with AI" on your profile to put one straight into your CV. Edit anything that is not true for you.` };
}

export function improve_bullet(message) {
  const text = extractPayload(message);
  if (text.length < 8) return { reply: 'Send me the line to improve, after a colon. For example:\nimprove this bullet: was responsible for handling customer complaints' };
  const options = offline.improveBullet(text).filter(Boolean);
  return { reply: `Here is a stronger way to write it:\n${options.map((o) => `- ${o}`).join('\n')}\n\nIf you have a number (how many, how much, how often), add it. Numbers are what recruiters remember.` };
}

export function write_cover_letter(message, ctx) {
  const f = profileFacts(ctx.content);
  if (needProfile(f)) return { reply: EMPTY };
  const job = extractJob(message);
  if (!job.title) return { reply: 'Which job is it for? Tell me the role, and the company if you know it. For example:\nwrite a cover letter for Data Analyst at MTN Uganda' };
  const country = extractCountry(message)?.id || 'AF';
  const letter = offline.coverLetter(ctx.content, { title: job.title, company: job.company, description: '' }, 'professional', country);
  return { reply: `${letter}\n\nFor a letter that uses the job advert itself, open Cover letters, paste the advert and pick a layout.` };
}

function needAdvert(message, what) {
  const jd = extractPayload(message);
  if (jd.length < 40) return { error: `To ${what} I need the job advert. Paste it after a colon, like this:\n${what === 'score your CV' ? 'ats score' : 'skill roadmap'}: <paste the job description here>` };
  return { jd };
}

export function ats_score(message, ctx) {
  const f = profileFacts(ctx.content);
  if (needProfile(f)) return { reply: EMPTY };
  const { jd, error } = needAdvert(message, 'score your CV');
  if (error) return { reply: error };
  const r = scoreResume(ctx.content, jd);
  const verdict = r.score >= 75 ? 'a strong match' : r.score >= 50 ? 'a fair match with gaps to close' : 'a weak match for now';
  const top = r.issues.slice(0, 3).map((i) => `- ${i.text}`).join('\n');
  return { reply: `Your CV scores ${r.score}/100 for this job, ${verdict}.\nKeywords found: ${r.matched.slice(0, 8).join(', ') || 'none'}.\nKeywords missing: ${r.missing.slice(0, 8).join(', ') || 'none'}.${top ? `\n\nWhat to fix:\n${top}` : ''}` };
}

export function interview_questions(message, ctx) {
  const f = profileFacts(ctx.content);
  if (needProfile(f)) return { reply: EMPTY };
  const job = extractJob(message);
  const qs = offline.interviewQuestions(ctx.content, job.title ? { title: job.title, company: job.company, description: '' } : null).slice(0, 6);
  return { reply: `Questions to prepare${job.title ? ` for a ${job.title} role` : ''}:\n\n${qs.map((x, i) => `${i + 1}. ${x.q}\n   Tip: ${x.tip}`).join('\n\n')}` };
}

export function skill_roadmap(message, ctx) {
  const f = profileFacts(ctx.content);
  if (needProfile(f)) return { reply: EMPTY };
  const { jd, error } = needAdvert(message, 'build a skill roadmap');
  if (error) return { reply: error };
  const { missing } = scoreResume(ctx.content, jd);
  if (!missing.length) return { reply: 'Good news: your CV already covers the main keywords in that advert. Work on adding numbers to your achievements instead.' };
  const steps = offline.roadmapSteps(missing, ctx.content);
  return { reply: `Skills this job asks for that your CV does not show yet:\n\n${steps.map((s) => `- ${s.skill} (about ${s.weeks} weeks): ${s.plan}`).join('\n')}` };
}

export function completeness(c) {
  const p = c.personal || {};
  const checks = [
    ['add your name, email and phone number', !!(p.fullName && p.email && p.phone)],
    ['write a professional summary', (c.summary || '').trim().length > 30],
    ['add your work experience', (c.experience || []).length > 0],
    ['add at least two achievements under a role', (c.experience || []).some((e) => (e.bullets || []).length >= 2)],
    ['add your education', (c.education || []).length > 0],
    ['list at least five skills', (c.skills || []).length >= 5],
  ];
  const done = checks.filter((x) => x[1]).length;
  return { pct: Math.round((done / checks.length) * 100), todo: checks.filter((x) => !x[1]).map((x) => x[0]) };
}
export function profile_completeness(_m, ctx) {
  const { pct, todo } = completeness(ctx.content);
  if (!todo.length) return { reply: 'Your profile is 100% complete. Next, create a resume and certify it so employers can verify it.' };
  return { reply: `Your profile is ${pct}% complete. Still to do:\n${todo.map((t) => `- ${t}`).join('\n')}\n\nNext step: ${todo[0]}.` };
}

export function years_experience(_m, ctx) {
  const f = profileFacts(ctx.content);
  if (!f.hasExperience) return { reply: 'You have no work experience on your profile yet. Add internships, volunteering or jobs under Profile and I will count them.' };
  const roles = (ctx.content.experience || []).length;
  const y = yearsOfExperience(ctx.content);
  return { reply: y < 1 ? `You have under one year of experience across ${roles} role${roles > 1 ? 's' : ''}.` : `You have about ${y} year${y > 1 ? 's' : ''} of experience across ${roles} role${roles > 1 ? 's' : ''}.` };
}

export function template_info(_m, ctx) {
  const f = profileFacts(ctx.content);
  const rec = f.level === 'none' || f.studying ? 'academic' : f.level === 'senior' ? 'executive' : 'timeline';
  const r = TEMPLATES.find((t) => t.id === rec);
  return { reply: `Templates: ${list(TEMPLATES.map((t) => t.name))}.\n\nFor your profile I would start with ${r.name}. ${r.desc}\n\nYou can switch templates at any time without retyping anything.` };
}

export function country_format(message) {
  const c = extractCountry(message);
  if (!c) return { reply: `Which country is the CV for? Tell me, for example "cv format in Uganda". I know the conventions for: ${list(Object.values(COUNTRIES).map((x) => x.name))}.` };
  const k = COUNTRIES[c.id];
  return { reply: `${cap(c.word)} falls under "${k.name}". Call it a ${k.doc}, on ${k.paper} paper. ${k.note}\nDate of birth: ${k.dob ? 'commonly included' : 'leave it off'}. Nationality: ${k.nationality ? 'commonly included' : 'leave it off'}. Referees: ${k.referees ? 'list them' : 'not needed'}.` };
}

export const no_experience_tips = () => ({ reply: 'With no work history, lead with what you do have:\n- Education first: your degree or certificate, school and dates.\n- Projects, coursework and anything you built or finished, with the tools you used.\n- Internships, volunteering and leadership roles count as experience.\n- Certificates and a skills list that matches the job.\nKeep the summary short and say which role you want.' });

export const verify_info = () => ({ reply: 'When you certify a resume, CV-Certify gives it a public document ID and stores a fingerprint of its contents. Anyone can enter the ID on the Verify page and see whether the CV is genuine and unchanged. If you edit the CV afterwards, it shows as changed until you certify it again, and you can revoke it at any time.' });

export const portfolio_info = () => ({ reply: 'Open Portfolio, pick a resume (a certified one adds a verification seal), choose a web address, then switch the page on. You get a public link you can share. Your email and phone only show if you tick the box for them.' });

export const salary_tip = () => ({ reply: 'Find the typical range for the role in your city, decide a number you would be happy with, and give a range with that number near the bottom rather than one fixed figure. Let them name a number first if you can, and tie your ask to results you have delivered.' });

/* ---------- registry: one entry per intent in INTENTS ---------- */
export const ACTIONS = {
  greet_user: { run: greet_user, title: 'Say hello', example: 'hello' },
  help_menu: { run: help_menu, title: 'Show this list', example: 'help' },
  write_summary: { run: write_summary, title: 'Write a professional summary', example: 'write my summary for a data analyst role' },
  improve_bullet: { run: improve_bullet, title: 'Improve a CV line', example: 'improve this bullet: was responsible for sales' },
  write_cover_letter: { run: write_cover_letter, title: 'Draft a cover letter', example: 'write a cover letter for Accountant at Stanbic' },
  ats_score: { run: ats_score, title: 'Score your CV against a job advert', example: 'ats score: <paste the job description>' },
  interview_questions: { run: interview_questions, title: 'Interview questions with tips', example: 'interview questions for a teller job' },
  skill_roadmap: { run: skill_roadmap, title: 'Skills to learn for a job', example: 'skill roadmap: <paste the job description>' },
  profile_completeness: { run: profile_completeness, title: 'Check how complete your profile is', example: 'how complete is my profile' },
  years_experience: { run: years_experience, title: 'Count your years of experience', example: 'how many years of experience do I have' },
  template_info: { run: template_info, title: 'Recommend a template', example: 'which template should I use' },
  country_format: { run: country_format, title: 'CV format for a country', example: 'cv format in Kenya' },
  no_experience_tips: { run: no_experience_tips, title: 'CV tips with no experience', example: 'I have no work experience' },
  verify_info: { run: verify_info, title: 'How verification works', example: 'how does verification work' },
  portfolio_info: { run: portfolio_info, title: 'Set up your portfolio page', example: 'how do I make a portfolio' },
  salary_tip: { run: salary_tip, title: 'Salary advice', example: 'how do I negotiate salary' },
};

export function fallback() {
  const ex = ['write a cover letter for Data Analyst', 'how complete is my profile', 'interview questions for a teller job', 'cv format in Uganda'];
  return `I did not quite get that. I am built for CV and job-search tasks, not open chat. Try something like:\n${ex.map((e) => `- ${e}`).join('\n')}\n\nType "help" to see everything I can do.`;
}

/** Route one message to one action. Never throws on user input. */
export function handleMessage(message, ctx = {}, { minConfidence = threshold() } = {}) {
  const started = performance.now();
  const text = String(message || '').trim();
  const done = (o) => ({ ...o, ms: Math.round((performance.now() - started) * 100) / 100 });
  if (!text) return done({ reply: fallback(), intent: null, confidence: 0, matched: false });
  const top = classify(text)[0];
  if (!top || top.confidence < minConfidence) return done({ reply: fallback(), intent: null, confidence: top ? top.confidence : 0, matched: false });
  const out = ACTIONS[top.intent].run(text, { content: ctx.content || {}, ...ctx });
  return done({ reply: out.reply, intent: top.intent, confidence: top.confidence, matched: true });
}

// The bank and the registry must describe the same intents.
for (const k of Object.keys(INTENTS)) if (!ACTIONS[k]) throw new Error(`Intent "${k}" has no action`);
for (const k of Object.keys(ACTIONS)) if (!INTENTS[k]) throw new Error(`Action "${k}" has no intent phrases`);
